-- ============================================================================
-- H4: Consequence Modelling joins the catalogue, the FOURTH course of the HSE
-- module.
--
-- Catalogue row (module 'hse'; path_order 64, directly above H3 lopa at 63;
-- prereq_slug NULL, the carried-over answer "no hard prerequisite inside a
-- module"; school left at its default, as every HSE course leaves it) plus the
-- three capstones and their eighteen graded fields, generated by
-- tools/course-waves/consequence/gen_course.py from the ENGINE'S OWN RUN
-- (h4_capstone.mjs through the vendored engines/hse/consequence.js), which it
-- refuses to write unless fields.json carries exactly that run's values and the
-- tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/consequence, because the 78 lessons,
-- the teaching lab (consequenceLab.js) and its three explorer panels ship in the
-- zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A consequence model turns a loss of
-- containment into physical effects, so the course teaches how much gets out
-- and where it goes (Associate), what a pool fire radiates (Professional) and
-- who is hurt by a fire, a blast or a toxic cloud, with what the engine does not
-- model (Expert), and grades each tier on its own question with numbers the
-- engine returns.
--
-- THE ENGINE. engines/hse/consequence.js, vendored sha-identical with
-- petrolord-engines 16fd6c9. Every input carries its unit in its name; every
-- result carries its model and source or a refusal naming its field; choked at
-- or below the critical pressure ratio; no spreading model; the plume reflects
-- at the ground; the solid flame of radius D/2 with the overhang refused;
-- Kinney and Graham over a judged range; every probit preset named by source.
--
-- WHAT IS GRADED. OKAN (Associate) grades three outflows, a pool diameter, a
-- plume concentration and a distance to a concentration; YOKRI (Professional)
-- grades the solid flame chain to a heat flux with a stated transmissivity;
-- PENNINGTON (Expert) grades a blast forward and inverse and four
-- probabilities, each on a preset an independent published check stands
-- behind. No single route quantity, no inverse of the normal CDF and no point
-- source heat radiation is graded.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, at each
-- field's own shipped tolerance: 0 collisions, and 0 pairwise. No prompt
-- states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('consequence', 'Consequence Modelling', 'hse', 64, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'consequence', 'beginner', 'associate',
  'OKAN, a gas and condensate platform loss of containment day',
  'How much gets out, and where it goes',
  'OKAN, a gas and condensate platform, on a loss of containment day. The properties below are illustrative, chosen for this exercise. Every pressure is absolute, and ambient is 101325 Pa. CONDENSATE: a hole of 0.041 m diameter in the stabiliser bottoms line, discharge coefficient 0.62, condensate density 786 kg/m3, 4.37 m of liquid above the hole and 310000 Pa above the liquid. RISER: a hole of 0.059 m diameter in the gas riser, discharge coefficient 0.62, gas at 4700000 Pa and 308.15 K, molar mass 0.0187 kg/mol, heat capacity ratio 1.28. VENT: the flash gas vent, the same gas through a hole of the same 0.059 m and the same discharge coefficient 0.62, at 128000 Pa and 308.15 K, molar mass 0.0187 kg/mol, heat capacity ratio 1.28. DECK SPILL: 24.8 m3 spilled on an open deck with no bund, spreading to a stated thickness of 0.017 m. PLUME: a sustained release of hydrogen sulphide (molar mass 34.08 g/mol) at 0.815 kg/s from a vent stack 12 m high, in a 4.2 m/s wind, Pasquill-Gifford class D, Briggs rural sigmas. The receptor is 620 m downwind, 35 m off the centreline and 1.7 m above the ground; convert at 25 C and 101325 Pa. REACH: the same 0.815 kg/s release from the same 12 m stack in the same 4.2 m/s wind at night, class E, read on the centreline 1.7 m above the ground, against a stated concentration of 21 mg/m3. Report six values: the condensate line mass rate, the gas riser mass rate and the flash gas vent mass rate, each in kg/s; the deck spill pool equivalent diameter in m; the concentration at the receptor in ppm; and the far distance, beyond the peak, at which the night plume meets the stated concentration, in m. Every value to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','okan_condensate_leak_mass_rate_kg_s', 'label','The condensate line mass rate', 'unit','kg/s', 'expected',15.977366614918033, 'tol',5e-07),
    jsonb_build_object('key','okan_gas_riser_choked_mass_rate_kg_s', 'label','The gas riser mass rate', 'unit','kg/s', 'expected',14.283249549626326, 'tol',5e-07),
    jsonb_build_object('key','okan_vent_subsonic_mass_rate_kg_s', 'label','The flash gas vent mass rate', 'unit','kg/s', 'expected',0.32964112031469717, 'tol',5e-07),
    jsonb_build_object('key','okan_deck_spill_equivalent_diameter_m', 'label','The deck spill pool equivalent diameter', 'unit','m', 'expected',43.097932739717095, 'tol',5e-07),
    jsonb_build_object('key','okan_plume_receptor_concentration_ppm', 'label','The concentration at the receptor', 'unit','ppm', 'expected',23.850025569186073, 'tol',5e-07),
    jsonb_build_object('key','okan_plume_far_distance_m', 'label','The far distance at which the stated concentration is met', 'unit','m', 'expected',1545.6774602801656, 'tol',5e-07)
  )
),
(
  'consequence', 'intermediate', 'professional',
  'YOKRI, a tank farm bund fire on a windy afternoon',
  'What the fire radiates, step by step',
  'YOKRI, a bund fire in a tank farm on a windy afternoon, worked through the solid flame model. The properties below are illustrative, chosen for this exercise. THE POOL: 31.5 m diameter, kerosene, its burning flux from the Babrauskas table the engine carries; heat of combustion 43000000 J/kg. THE AIR: wind at 10 m 6 m/s, air density 1.2 kg/m3, air kinematic viscosity 1.48e-5 m2/s. Take the flame length by Thomas with wind and the tilt from the wind, the flame base radius half the pool diameter. THE FLAME SURFACE: compute the surface emissive power two ways, from the diameter (Mudan) and from a radiative fraction of 0.235 with a soot fraction of 0.8 and the engine''s default soot emissive power; the heat flux uses the second. THE TARGET: at ground level 72 m downwind of the pool centre, the flame leaning toward it, with a stated atmospheric transmissivity of 0.765. Report six values: the flame length with wind in m; the flame tilt from the vertical in degrees; the surface emissive power from the diameter and the surface emissive power from the radiative fraction with soot, each in W/m2; the maximum view factor at the target; and the heat flux at the target in W/m2. The view factor to twelve decimals, every other value to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','yokri_flame_length_with_wind_m', 'label','The flame length with wind', 'unit','m', 'expected',20.618159361645755, 'tol',5e-07),
    jsonb_build_object('key','yokri_flame_tilt_deg', 'label','The flame tilt from the vertical', 'unit','degrees', 'expected',53.02368839919855, 'tol',5e-07),
    jsonb_build_object('key','yokri_surface_emissive_power_mudan_w_m2', 'label','The surface emissive power from the diameter', 'unit','W/m2', 'expected',22738.722971011157, 'tol',5e-07),
    jsonb_build_object('key','yokri_surface_emissive_power_actual_w_m2', 'label','The surface emissive power from the radiative fraction with soot', 'unit','W/m2', 'expected',37784.162897552, 'tol',5e-07),
    jsonb_build_object('key','yokri_view_factor_max', 'label','The maximum view factor at the target', 'unit','dimensionless', 'expected',0.04602429827467467, 'tol',5e-13),
    jsonb_build_object('key','yokri_solid_flame_heat_flux_w_m2', 'label','The heat flux at the target', 'unit','W/m2', 'expected',1330.3270311907092, 'tol',5e-07)
  )
),
(
  'consequence', 'advanced', 'expert',
  'PENNINGTON, a storage terminal and the harm three hazards do',
  'Who is hurt, and with what probability',
  'PENNINGTON, a storage terminal, and the harm a vapour cloud explosion, a fire and two toxic releases do to the people nearby. The properties below are illustrative, chosen for this exercise. Ambient is 101325 Pa. BLAST: the cloud is stated as 2650 kg of TNT, a free air burst, Kinney and Graham. The control room is 145 m away. Find also the distance at which the peak side-on overpressure is 19800 Pa. A workshop takes 65000 Pa; use the HSC overpressure fatality probit. FIRE: a heat flux of 11900 W/m2 for 60 s, the eisenberg thermal probit. CHLORINE: 270 ppm for 20 minutes, the lees-chlorine toxic probit. AMMONIA: 11050 mg/m3 for 12 minutes, the lees-ammonia toxic probit, molar mass 17.031 g/mol, the air at 288.15 K and 101325 Pa. Report six values: the peak side-on overpressure at the control room in Pa; the distance at which the stated overpressure is reached, in m; the overpressure fatality probability in the workshop; the thermal lethality probability; the chlorine lethality probability; and the ammonia lethality probability. Every value to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','pennington_blast_overpressure_pa', 'label','The peak side-on overpressure at the control room', 'unit','Pa', 'expected',9394.478439157123, 'tol',5e-07),
    jsonb_build_object('key','pennington_blast_distance_for_overpressure_m', 'label','The distance at which the stated overpressure is reached', 'unit','m', 'expected',86.70704808709807, 'tol',5e-07),
    jsonb_build_object('key','pennington_overpressure_fatality_probability', 'label','The overpressure fatality probability in the workshop', 'unit','probability', 'expected',0.3241114439521945, 'tol',5e-07),
    jsonb_build_object('key','pennington_thermal_lethality_probability', 'label','The thermal lethality probability', 'unit','probability', 'expected',0.16721559730785146, 'tol',5e-07),
    jsonb_build_object('key','pennington_toxic_lethality_probability', 'label','The chlorine lethality probability', 'unit','probability', 'expected',0.4079467919883339, 'tol',5e-07),
    jsonb_build_object('key','pennington_ammonia_lethality_probability', 'label','The ammonia lethality probability', 'unit','probability', 'expected',0.2606861594816057, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
